// The knowledge base as data: the plays registry, stages and templates, parsed
// from openknowledge/ front-matter. The bundled snapshot is generated by
// scripts/build-knowledge.ts; a project's own openknowledge/ overrides it at
// runtime through loadKnowledge + mergeKnowledge. Pure, no `$`.

import type { Knowledge, PlayDef, PlayView, StageDoc, StageId, TemplateName } from '../../types'
import { PLAY_ENFORCEMENT, STAGE_IDS, STAGE_META, STAGE_PLAYS, TEMPLATE_FILES, TEMPLATE_NAMES } from './constants'
import { BUNDLED } from './knowledge.generated'
import { parseFrontmatter } from './yaml'

export const DEFAULT_KNOWLEDGE_ROOT = 'openknowledge'

// ---------------------------------------------------------------------------
// Bundled snapshot and the fixed file list
// ---------------------------------------------------------------------------

function clonePlay(p: PlayDef): PlayDef {
  return { ...p, prerequisites: [...p.prerequisites], outputs: [...p.outputs], tags: [...p.tags] }
}

/** The snapshot generated from this repo's openknowledge/. Fresh copies: callers may keep them. */
export function bundledKnowledge(): Knowledge {
  return {
    source: 'bundled',
    root: DEFAULT_KNOWLEDGE_ROOT,
    title: BUNDLED.title,
    version: BUNDLED.version,
    summary: BUNDLED.summary,
    plays: BUNDLED.plays.map(clonePlay),
    stages: BUNDLED.stages.map((s) => ({ ...s })),
    templates: { ...BUNDLED.templates },
    issues: [],
  }
}

function cleanRoot(root: string): string {
  const r = root.trim().replace(/\\/g, '/').replace(/^\.\//, '').replace(/\/+$/, '')
  return r === '' ? DEFAULT_KNOWLEDGE_ROOT : r
}

/** Root-relative paths worth reading. No directory listing exists in the engine, so this is the fixed candidate list. */
export function knowledgeRelPaths(): string[] {
  return [
    'INDEX.md',
    ...STAGE_IDS.map((id) => STAGE_META[id].knowledgePath),
    ...BUNDLED.plays.map((p) => p.path),
    ...TEMPLATE_NAMES.map((n) => TEMPLATE_FILES[n]),
  ]
}

/** Repo-relative paths to read under `root` (INDEX.md, stages, plays, templates). */
export function knowledgeFiles(root: string): string[] {
  const r = cleanRoot(root)
  return knowledgeRelPaths().map((p) => `${r}/${p}`)
}

// ---------------------------------------------------------------------------
// Parsing a knowledge root
// ---------------------------------------------------------------------------

function text(v: unknown): string {
  if (typeof v === 'string') return v.trim()
  if (typeof v === 'number') return String(v)
  return ''
}

function textList(v: unknown): string[] {
  if (!Array.isArray(v)) return []
  const out: string[] = []
  for (const x of v) {
    const s = text(x)
    if (s !== '') out.push(s)
  }
  return out
}

function firstHeading(body: string): string {
  const m = /^#\s+(.+?)\s*#*\s*$/m.exec(body)
  return m?.[1] ?? ''
}

/** `stage-3-build` -> 'build'. The number is the fallback when the name is not a stage id. */
function stageFromName(value: unknown): StageId | null {
  const m = /^stage-(\d)-([a-z]+)$/.exec(text(value))
  if (!m) return null
  const named = STAGE_IDS.find((id) => id === m[2])
  return named ?? STAGE_IDS[Number(m[1]) - 1] ?? null
}

function stageOfPlay(n: number): StageId {
  for (const id of STAGE_IDS) if (STAGE_PLAYS[id].includes(n)) return id
  return 'build'
}

function pad2(n: number): string {
  return n < 10 ? `0${n}` : String(n)
}

/** Wiki front-matter links ("[[openknowledge/plays/play-07-…]]") and bare numbers both name a play. */
function prerequisiteNumber(entry: unknown): number | null {
  if (typeof entry === 'number' && Number.isInteger(entry)) return entry
  const m = /play-(\d{1,2})\b/.exec(text(entry))
  return m ? Number(m[1]) : null
}

function parsePlay(n: number, file: string, source: string, issues: string[]): PlayDef {
  const label = `plays/${file}`
  const fm = parseFrontmatter(source)
  if (!fm.hasFrontmatter) issues.push(`${label}: no front-matter; using the file name and first heading`)
  const d = fm.data

  const id = text(d.id) || `okf-play-${pad2(n)}-${file.replace(/^play-\d+-/, '').replace(/\.md$/, '')}`
  const idNumber = /^okf-play-(\d{1,2})\b/.exec(id)
  if (idNumber && Number(idNumber[1]) !== n) issues.push(`${label}: id "${id}" disagrees with the file name (play ${n})`)

  let stage = stageFromName(d.stage)
  if (stage === null) {
    stage = stageOfPlay(n)
    issues.push(`${label}: stage "${text(d.stage)}" is not stage-N-name; filed under ${stage}`)
  }

  const prerequisites: number[] = []
  const rawPrereqs = Array.isArray(d.prerequisites) ? d.prerequisites : []
  if (d.prerequisites !== undefined && !Array.isArray(d.prerequisites)) issues.push(`${label}: prerequisites is not a list`)
  for (const entry of rawPrereqs) {
    const p = prerequisiteNumber(entry)
    if (p === null || p < 1 || p > 99) issues.push(`${label}: prerequisite ${JSON.stringify(entry)} does not name a play`)
    else if (p === n) issues.push(`${label}: play ${n} lists itself as a prerequisite`)
    else if (!prerequisites.includes(p)) prerequisites.push(p)
  }

  return {
    n,
    id,
    title: text(d.title) || firstHeading(fm.body) || `Play ${pad2(n)}`,
    stage,
    entryPoint: d.entry_point === true || text(d.entry_point) === 'true',
    prerequisites,
    outputs: textList(d.outputs),
    summary: text(d.summary),
    path: label,
    tags: textList(d.tags),
  }
}

function parseStage(number: number, file: string, source: string, issues: string[]): StageDoc | null {
  const label = `stages/${file}`
  const fm = parseFrontmatter(source)
  if (!fm.hasFrontmatter) issues.push(`${label}: no front-matter; using the file name and first heading`)
  const declared = typeof fm.data.stage_number === 'number' ? fm.data.stage_number : number
  const id = STAGE_IDS[declared - 1]
  if (id === undefined) {
    issues.push(`${label}: stage number ${declared} is outside 1..6; skipped`)
    return null
  }
  return {
    id,
    number: declared,
    title: text(fm.data.title) || firstHeading(fm.body) || STAGE_META[id].name,
    summary: text(fm.data.summary),
    path: label,
  }
}

/** Drop the wiki front-matter of a template, but keep a template's own (the verifier agent's `name:` block). */
export function stripWikiFrontmatter(source: string): string {
  const fm = parseFrontmatter(source)
  if (!fm.hasFrontmatter) return source
  const id = fm.data.id
  const wiki = fm.data.type === 'template' || (typeof id === 'string' && id.startsWith('okf-'))
  return wiki ? fm.body.replace(/^(?:[ \t]*\r?\n)+/, '') : source
}

function normalizeKeys(files: Record<string, string>, root: string): Record<string, string> {
  const r = `${cleanRoot(root)}/`
  const out: Record<string, string> = {}
  for (const key of Object.keys(files).sort()) {
    let k = key.replace(/\\/g, '/').replace(/^\.\//, '')
    if (k.startsWith(r)) k = k.slice(r.length)
    const value = files[key]
    if (value !== undefined) out[k] = value
  }
  return out
}

/**
 * Parse a knowledge root. `files` is keyed by path relative to `root`
 * (a key still carrying the `root/` prefix is accepted). Never throws: whatever
 * cannot be parsed becomes an entry in `issues`.
 */
export function loadKnowledge(files: Record<string, string>, root: string): Knowledge {
  const r = cleanRoot(root)
  const byPath = normalizeKeys(files, r)
  const issues: string[] = []

  let title = ''
  let version = ''
  let summary = ''
  const index = byPath['INDEX.md']
  if (index === undefined) {
    issues.push('INDEX.md: not found')
  } else {
    const fm = parseFrontmatter(index)
    if (!fm.hasFrontmatter) issues.push('INDEX.md: no front-matter')
    title = text(fm.data.title) || firstHeading(fm.body)
    version = text(fm.data.version)
    summary = text(fm.data.summary)
    if (title === '') issues.push('INDEX.md: no title')
  }

  const plays: PlayDef[] = []
  const stages: StageDoc[] = []
  for (const [path, source] of Object.entries(byPath)) {
    const play = /^plays\/(play-(\d{1,2})-[^/]+\.md)$/.exec(path)
    if (play) {
      const n = Number(play[2])
      const parsed = parsePlay(n, play[1] ?? '', source, issues)
      if (plays.some((p) => p.n === n)) issues.push(`${path}: a second file for play ${n}; ignored`)
      else plays.push(parsed)
      continue
    }
    const stage = /^stages\/((\d{2})-[^/]+\.md)$/.exec(path)
    if (stage) {
      const parsed = parseStage(Number(stage[2]), stage[1] ?? '', source, issues)
      if (parsed && !stages.some((s) => s.number === parsed.number)) stages.push(parsed)
    }
  }
  plays.sort((a, b) => a.n - b.n)
  stages.sort((a, b) => a.number - b.number)
  if (plays.length === 0) issues.push('plays/: no play-NN-*.md files found')

  const templates: Partial<Record<TemplateName, string>> = {}
  for (const name of TEMPLATE_NAMES) {
    const source = byPath[TEMPLATE_FILES[name]]
    if (source !== undefined) templates[name] = stripWikiFrontmatter(source)
  }

  return { source: 'repo', root: r, title, version, summary, plays, stages, templates, issues }
}

/** Unresolved prerequisites and dependency cycles. Front-matter is the truth for the graph. */
export function validatePlayGraph(plays: PlayDef[]): string[] {
  const issues: string[] = []
  const known = new Set(plays.map((p) => p.n))
  for (const p of plays) {
    for (const q of p.prerequisites) {
      if (!known.has(q)) issues.push(`Play ${pad2(p.n)}: prerequisite Play ${pad2(q)} is not defined`)
    }
  }
  const { left } = resolveOrder(plays.filter((p) => p.prerequisites.every((q) => known.has(q))))
  if (left.length > 0) issues.push(`Dependency cycle among plays ${left.map(pad2).join(', ')}`)
  return issues
}

/** `override` wins per play number, stage number and template; empty top-level text falls back to `base`. */
export function mergeKnowledge(base: Knowledge, override: Knowledge): Knowledge {
  const plays = new Map<number, PlayDef>()
  for (const p of base.plays) plays.set(p.n, p)
  for (const p of override.plays) plays.set(p.n, p)
  const stages = new Map<number, StageDoc>()
  for (const s of base.stages) stages.set(s.number, s)
  for (const s of override.stages) stages.set(s.number, s)
  const merged = [...plays.values()].sort((a, b) => a.n - b.n)
  return {
    source: override.source,
    root: override.root,
    title: override.title || base.title,
    version: override.version || base.version,
    summary: override.summary || base.summary,
    plays: merged,
    stages: [...stages.values()].sort((a, b) => a.number - b.number),
    templates: { ...base.templates, ...override.templates },
    issues: [...base.issues, ...override.issues, ...validatePlayGraph(merged)],
  }
}

// ---------------------------------------------------------------------------
// The dependency graph
// ---------------------------------------------------------------------------

export function playByNumber(plays: PlayDef[], n: number): PlayDef | undefined {
  return plays.find((p) => p.n === n)
}

export function prerequisitesOf(plays: PlayDef[], n: number): number[] {
  return [...(playByNumber(plays, n)?.prerequisites ?? [])]
}

/** Enabled plays that list `n` as a prerequisite: they block disabling it. */
export function dependentsOf(plays: PlayDef[], n: number, enabled: number[]): number[] {
  return plays
    .filter((p) => p.prerequisites.includes(n) && enabled.includes(p.n))
    .map((p) => p.n)
    .sort((a, b) => a - b)
}

/** Prerequisites of `n` that are not enabled. */
export function unmetPrerequisites(plays: PlayDef[], n: number, enabled: number[]): number[] {
  return prerequisitesOf(plays, n).filter((q) => !enabled.includes(q))
}

export function playViews(args: {
  plays: PlayDef[]
  enabled: number[]
  evidence: Record<number, { label: string; ok: boolean }[]>
}): PlayView[] {
  return args.plays.map((p) => ({
    ...p,
    enabled: args.enabled.includes(p.n),
    unmet: unmetPrerequisites(args.plays, p.n, args.enabled),
    dependents: dependentsOf(args.plays, p.n, args.enabled),
    enforcedBy: [...(PLAY_ENFORCEMENT[p.n] ?? [])],
    evidence: [...(args.evidence[p.n] ?? [])],
  }))
}

function resolveOrder(plays: PlayDef[]): { done: number[]; left: number[] } {
  const known = new Set(plays.map((p) => p.n))
  const done: number[] = []
  const rest = [...plays].sort((a, b) => a.n - b.n)
  for (;;) {
    const ready = rest.find((p) => p.prerequisites.every((q) => !known.has(q) || done.includes(q)))
    if (!ready) break
    done.push(ready.n)
    rest.splice(rest.indexOf(ready), 1)
  }
  return { done, left: rest.map((p) => p.n) }
}

/** Prerequisites first; the lowest play number wins ties. A cycle never loops: its members are appended last. */
export function topologicalPlayOrder(plays: PlayDef[]): number[] {
  const { done, left } = resolveOrder(plays)
  return [...done, ...left]
}

/** "Play 07 · Hooks as Build-Time Guardrails": the title without its "Play 07:" prefix. */
export function playLabel(plays: PlayDef[], n: number): string {
  const title = (playByNumber(plays, n)?.title ?? '').replace(/^Play\s+\d+\s*[:\-—]\s*/i, '')
  return title === '' ? `Play ${pad2(n)}` : `Play ${pad2(n)} · ${title}`
}

/** Plays filed under each stage, INDEX order (by number). */
export function playsByStage(plays: PlayDef[]): Record<StageId, PlayDef[]> {
  const out: Record<StageId, PlayDef[]> = { plan: [], design: [], build: [], test: [], deploy: [], maintain: [] }
  for (const p of [...plays].sort((a, b) => a.n - b.n)) out[p.stage].push(p)
  return out
}
